root = tree.getroot()

print("=== JOINTS ===")
for jnt in root.iter("joint"):
    print(jnt.attrib)

print("\n=== FREEJOINT ===")
for fj in root.iter("freejoint"):
    print(fj.attrib)

print("\n=== ACTUATORS ===")
for act in root.iter("actuator"):
    for child in act:
        print(child.tag, child.attrib)

print("\n=== SITES ===")
for site in root.iter("site"):
    print(site.attrib)

print("\n=== EQUALITY ===")
for eq in root.iter("equality"):
    for child in eq:
        print(child.tag, child.attrib)

